    345,365,353,352,350,382,779,386,362,361,235,323,331,343,258,243,
    397,397,427,435,391,390,374,358,340,346,291,333,329,358,354,343,
    349,366,358,346,400,381,355,358,359,354,360,724,731,745,749,745,
    190,193,378,380,486,585,337,306,235,313,863.88,252.5,357.11,192.2,187.45,183.55,
    208.92,614.58,577.65,612.23,193.61,186.77,208.16,165.91,164.26,191.25,183.82,162.69,162.22,165.82,113.46,140.01,
    123.16,138.59,155.69,314.07,301.76,180.09,173.69,135.94,181.29,144.77,168.42,99.05,173.75,122.61,113.36,64.61,
    99.71,70.85,96.6,82.88,123.82,72.16,119.19,65.19,81.46,74.34,93.29,80.09,109.11,48.32,88.26,71.01,
    57.36,68.91,126.03,58.68,56.33,90.93,59.41,62.24,54.35,65.06,66.68,50.15,61.4,73.78,53.17,66.59,
    67.45,58.83,64.04,57.25,65.08,88.63,56.93,65.87,62.21,47.59,69.41,73.91,59.3,969.58,821.93,710.58,
    663.79,124.39,113.79,109.17,117.64,78.61,126.64,84.07,133.93,224.87,210.12,212.33,128.76,105.38,151.03,223.57,
    272.58,309.23,305.62,281.23,292.51,261.51,241.76,248.14,392.16,326.25,237.04,289.67,287.6,315.02,356.72,877.62,
    100.51,29.37,69.54,132.24,174.1,133.6,199.54,159.62,157.08,277.01,259.14,221.54,173.44,152.29,142.76,1312.14,
    1211.53,1269.87,1289.42,1177.98,1046.51,900.58,762.59,668.52,541.83,537.35,543.84,528.89,476,476.95,457.87,417.55,
    372.78,335.09,325.16,303.83,268,165.74,138.22,197.07,189.79,147.41,176.6,125.91,139.04,324.35,524.13,745.36,
    707.8,637.37,586.23,624.25,574.98,467.7,453.38,484.94,533.14,691.56,696.53,630.48,621.01,687.47,773.51,755.37,
    695.54,628.07,352.62,39.88,45.04,57.09,46.59,44.43,91.97,122.15,109.09,77.8,1118,1110,1095}';
  p_sid int[];
  p_tid int[];
  g record;
  d_sid int[];
  d_ts timestamptz[];
  n_deleted int;
  n_listed int[];
  n_gone int[];
BEGIN
  -- The loader lock, as the loader's own lock() takes it, but with a bound: the previous release's load still runs
  -- while migrate does, and a long loader transaction must fail the deploy (it is tried again), never hang it.
  PERFORM set_config('lock_timeout', '120s', true);
  BEGIN
    PERFORM 1 FROM app_meta WHERE key = 'loader_lock' FOR UPDATE;
  EXCEPTION WHEN lock_not_available THEN
    RAISE EXCEPTION '184 orphans: the loader lock was busy for 120 s: nothing deleted';
  END;
  IF NOT FOUND THEN
    RAISE EXCEPTION '184 orphans: no loader_lock row';
  END IF;

  -- Each key's primary series and its daily-mean twin (null where the registry sync has not made them).
  SELECT array_agg(p.id ORDER BY q.ix), array_agg(t.id ORDER BY q.ix)
    INTO p_sid, p_tid
    FROM unnest(p_keys) WITH ORDINALITY AS q(key, ix)
    LEFT JOIN series p ON p.source_id = 'NL-1' AND p.provider_key = q.key AND p.role = 'primary'
    LEFT JOIN series t ON t.source_id = 'NL-1' AND t.provider_key = q.key || '/GEM24H' AND t.role = 'twin'
                      AND t.aggregate = 'mean';

  -- The guards, over the listed rows that are present.
  WITH l AS (SELECT p_sid[u.ix] AS sid, p_tid[u.ix] AS tid, to_timestamp(u.e) AS ts, u.v
             FROM unnest(p_ix, p_epoch, p_value) AS u(ix, e, v))
  SELECT count(*) AS present,
      count(*) FILTER (WHERE (o.qc & 512) = 0) AS bit512,
      count(*) FILTER (WHERE b.origin IS DISTINCT FROM 'backfill') AS origin,
      count(*) FILTER (WHERE o.ts >= timestamptz '2026-08-01 00:00:00+00') AS floor,
      count(*) FILTER (WHERE o.value <> l.v) AS value,
      count(*) FILTER (WHERE l.tid IS NULL) AS twin_series,
      count(*) FILTER (WHERE l.tid IS NOT NULL AND (w.value IS NULL OR w.value <> l.v)) AS twin_row,
      count(*) FILTER (WHERE x.series_id IS NOT NULL) AS latest,
      count(*) FILTER (WHERE EXISTS (SELECT 1 FROM obs_revision r WHERE r.series_id = o.series_id AND r.ts = o.ts)) AS revision
    INTO g
    FROM l
    JOIN obs o ON o.series_id = l.sid AND o.ts = l.ts
           AND o.ts >= timestamptz '1990-01-01 00:00:00+00' AND o.ts < timestamptz '2023-12-31 00:00:00+00'
    LEFT JOIN ingest_batch b ON b.id = o.batch_id
    LEFT JOIN obs w ON w.series_id = l.tid AND w.ts = l.ts
           AND w.ts >= timestamptz '1990-01-01 00:00:00+00' AND w.ts < timestamptz '2023-12-31 00:00:00+00'
    LEFT JOIN obs_latest x ON x.series_id = o.series_id AND x.ts = o.ts;
  IF g.bit512 + g.origin + g.floor + g.value + g.twin_series + g.twin_row + g.latest + g.revision > 0 THEN
    RAISE EXCEPTION '184 orphans: % of % present rows fail a guard (bit512 %, origin %, floor %, value %, twin_series %, twin_row %, latest %, revision %): nothing deleted',
      g.bit512 + g.origin + g.floor + g.value + g.twin_series + g.twin_row + g.latest + g.revision, g.present,
      g.bit512, g.origin, g.floor, g.value, g.twin_series, g.twin_row, g.latest, g.revision;
  END IF;

  -- Per key: the rows listed (the arrays only; every present row is deleted, or the block has aborted).
  SELECT array_agg(c.n ORDER BY c.ix) INTO n_listed
    FROM (SELECT q.ix, count(u.ix)::int AS n
          FROM generate_subscripts(p_keys, 1) AS q(ix) LEFT JOIN unnest(p_ix) AS u(ix) ON u.ix = q.ix
          GROUP BY q.ix) c;

  WITH l AS (SELECT p_sid[u.ix] AS sid, to_timestamp(u.e) AS ts
             FROM unnest(p_ix, p_epoch) AS u(ix, e)),
       d AS (DELETE FROM obs o USING l
             WHERE o.series_id = l.sid AND o.ts = l.ts
               AND o.ts >= timestamptz '1990-01-01 00:00:00+00' AND o.ts < timestamptz '2023-12-31 00:00:00+00'
             RETURNING o.series_id, o.ts)
  SELECT array_agg(d.series_id), array_agg(d.ts), count(*) INTO d_sid, d_ts, n_deleted FROM d;
  IF n_deleted <> g.present THEN
    RAISE EXCEPTION '184 orphans: deleted % rows, % were present', n_deleted, g.present;
  END IF;

  IF n_deleted > 0 THEN
    INSERT INTO obs_1h AS r (series_id, bucket, vmin, vmax, vavg, vlast, n, qc_or)
    SELECT o.series_id, t.bucket, min(o.value), max(o.value), avg(o.value)::real,
           (array_agg(o.value ORDER BY o.ts DESC))[1], count(*)::int, bit_or(o.qc)
    FROM (SELECT DISTINCT u.series_id, date_bin('1 hour', u.ts, timestamptz '2000-01-01 00:00:00+00') AS bucket
            FROM unnest(d_sid, d_ts) AS u(series_id, ts)) t
    JOIN obs o ON o.series_id = t.series_id AND o.ts >= t.bucket AND o.ts < t.bucket + interval '1 hour'
              AND date_bin('1 hour', o.ts, timestamptz '2000-01-01 00:00:00+00') = t.bucket
              AND o.ts >= timestamptz '1990-01-01 00:00:00+00' AND o.ts < timestamptz '2023-12-31 00:00:00+00'
    GROUP BY o.series_id, t.bucket
    ON CONFLICT (series_id, bucket) DO UPDATE
      SET vmin = EXCLUDED.vmin, vmax = EXCLUDED.vmax, vavg = EXCLUDED.vavg, vlast = EXCLUDED.vlast,
          n = EXCLUDED.n, qc_or = EXCLUDED.qc_or
      WHERE (r.vmin, r.vmax, r.vavg, r.vlast, r.n, r.qc_or)
            IS DISTINCT FROM (EXCLUDED.vmin, EXCLUDED.vmax, EXCLUDED.vavg, EXCLUDED.vlast, EXCLUDED.n, EXCLUDED.qc_or);
    -- A bucket no row holds any more is deleted (n > 0 is a CHECK, and the store never empties one).
    DELETE FROM obs_1h r
    USING (SELECT DISTINCT u.series_id, date_bin('1 hour', u.ts, timestamptz '2000-01-01 00:00:00+00') AS bucket
            FROM unnest(d_sid, d_ts) AS u(series_id, ts)) t
    WHERE r.series_id = t.series_id AND r.bucket = t.bucket
      AND NOT EXISTS (SELECT 1 FROM obs o WHERE o.series_id = t.series_id
                        AND o.ts >= t.bucket AND o.ts < t.bucket + interval '1 hour'
                        AND o.ts >= timestamptz '1990-01-01 00:00:00+00' AND o.ts < timestamptz '2023-12-31 00:00:00+00');
    INSERT INTO obs_1d AS r (series_id, bucket, vmin, vmax, vavg, vlast, n, qc_or)
    SELECT o.series_id, t.bucket, min(o.value), max(o.value), avg(o.value)::real,
           (array_agg(o.value ORDER BY o.ts DESC))[1], count(*)::int, bit_or(o.qc)
    FROM (SELECT DISTINCT u.series_id, date_bin('1 day', u.ts, timestamptz '2000-01-01 00:00:00+00') AS bucket
            FROM unnest(d_sid, d_ts) AS u(series_id, ts)) t
    JOIN obs o ON o.series_id = t.series_id AND o.ts >= t.bucket AND o.ts < t.bucket + interval '1 day'
              AND date_bin('1 day', o.ts, timestamptz '2000-01-01 00:00:00+00') = t.bucket
              AND o.ts >= timestamptz '1990-01-01 00:00:00+00' AND o.ts < timestamptz '2023-12-31 00:00:00+00'
    GROUP BY o.series_id, t.bucket
    ON CONFLICT (series_id, bucket) DO UPDATE
      SET vmin = EXCLUDED.vmin, vmax = EXCLUDED.vmax, vavg = EXCLUDED.vavg, vlast = EXCLUDED.vlast,
          n = EXCLUDED.n, qc_or = EXCLUDED.qc_or
      WHERE (r.vmin, r.vmax, r.vavg, r.vlast, r.n, r.qc_or)
            IS DISTINCT FROM (EXCLUDED.vmin, EXCLUDED.vmax, EXCLUDED.vavg, EXCLUDED.vlast, EXCLUDED.n, EXCLUDED.qc_or);
    -- A bucket no row holds any more is deleted (n > 0 is a CHECK, and the store never empties one).
    DELETE FROM obs_1d r
    USING (SELECT DISTINCT u.series_id, date_bin('1 day', u.ts, timestamptz '2000-01-01 00:00:00+00') AS bucket
            FROM unnest(d_sid, d_ts) AS u(series_id, ts)) t
    WHERE r.series_id = t.series_id AND r.bucket = t.bucket
      AND NOT EXISTS (SELECT 1 FROM obs o WHERE o.series_id = t.series_id
                        AND o.ts >= t.bucket AND o.ts < t.bucket + interval '1 day'
                        AND o.ts >= timestamptz '1990-01-01 00:00:00+00' AND o.ts < timestamptz '2023-12-31 00:00:00+00');
  END IF;

  SELECT array_agg(coalesce(c.n, 0) ORDER BY q.ix) INTO n_gone
    FROM generate_subscripts(p_keys, 1) AS q(ix)
    LEFT JOIN (SELECT u.s, count(*)::int AS n FROM unnest(d_sid) AS u(s) GROUP BY u.s) c ON c.s = p_sid[q.ix];
  FOR i IN 1 .. array_length(p_keys, 1) LOOP
    RAISE NOTICE '184 orphans: % listed %, deleted %, absent %',
      p_keys[i], n_listed[i], n_gone[i], n_listed[i] - n_gone[i];
  END LOOP;
END
$$;

-- migrate:down
-- Nothing: the deleted rows do not come back (data is never restored by a down, and a replay with today's
-- normaliser does not produce them; their values are in the /GEM24H twins).
